<?php
require_once __DIR__.'/_data.php';
$db=storefront_db();$customer=$db?marketplace_customer($db):null;if(!$customer)legacy_redirect('masuk?next=bantuan-pesanan');$cid=(int)$customer['id'];marketplace_service_install($db);
$id=(int)($_GET['id']??0);$case=marketplace_service_get($db,$id);if(!$case||(int)$case['customer_id']!==$cid){http_response_code(404);$case=null;}
if($case&&is_post()){
 if(!CSRF::verify()){flash('error','Token keamanan tidak valid.');legacy_redirect('bantuan-pesanan/'.$id);}
 $msg=trim((string)($_POST['message']??''));if($msg!==''){marketplace_service_add_message($db,$id,'customer',$cid,$msg);$db->prepare("UPDATE marketplace_service_cases SET status=CASE WHEN status IN('resolved','closed','rejected') THEN status ELSE 'waiting_admin' END,updated_at=NOW() WHERE id=?")->execute([$id]);if(function_exists('marketplace_wa_enqueue_admin'))marketplace_wa_enqueue_admin($db,'service_case','Balasan pelanggan pada '.$case['case_number'].' / '.$case['order_number'],'mkt-case-reply-c-'.$id.'-'.time(),(int)$case['order_id']);flash('success','Pesan terkirim.');}
 legacy_redirect('bantuan-pesanan/'.$id);
}
$messages=$case?marketplace_service_messages($db,$id):[];$pageTitle=$case?('Bantuan '.$case['case_number']):'Pengajuan Tidak Ditemukan';$activePage='support';require __DIR__.'/_header.php';
?>
