<main class="inner-page"><section class="store-container order-page-head"><div><span class="hero-label"><i class="bi bi-headset"></i> BANTUAN PESANAN</span><h1><?= $case?e($case['case_number']):'Tidak ditemukan'?></h1><p><?= $case?e($case['order_number']):''?></p></div><?php if($case):?><span class="order-status-pill processing"><?=e(marketplace_service_status_label((string)$case['status']))?></span><?php endif;?></section><?php if(!$case):?><section class="store-container checkout-box">Pengajuan tidak ditemukan.</section><?php else:?><section class="store-container case-layout"><section class="checkout-box"><div class="checkout-box-title"><span><i class="bi bi-chat-dots"></i></span><div><small>PERCAKAPAN</small><h2><?=e(marketplace_service_type_label((string)$case['case_type']))?></h2></div></div><div class="case-chat"><?php foreach($messages as $m):?><div class="case-bubble <?=e($m['sender_type'])?>"><b><?= $m['sender_type']==='customer'?'Anda':($m['sender_type']==='admin'?'Admin':'Sistem')?></b><div><?=nl2br(e($m['message']))?></div><small><?=e(date('d M Y H:i',strtotime((string)$m['created_at'])))?></small></div><?php endforeach;?></div><?php if(!in_array($case['status'],['closed'],true)):?><form method="post" class="case-reply" style="margin-top:16px"><?=CSRF::input()?><textarea name="message" required placeholder="Tulis balasan..."></textarea><button class="btn-primary-store" style="margin-top:8px"><i class="bi bi-send"></i> Kirim Balasan</button></form><?php endif;?></section><aside class="checkout-box"><div class="case-meta"><div><span>Status</span><b><?=e(marketplace_service_status_label((string)$case['status']))?></b></div><div><span>Jenis</span><b><?=e(marketplace_service_type_label((string)$case['case_type']))?></b></div><div><span>Alasan</span><b><?=e($case['reason']?:'-')?></b></div><div><span>Refund</span><b><?=e(strtoupper((string)$case['refund_status']))?><?= (float)$case['refund_amount']>0?' • '.rupiah($case['refund_amount']):''?></b></div><?php if($case['refund_reference']):?><div><span>Referensi Refund</span><b><?=e($case['refund_reference'])?></b></div><?php endif;?></div><a class="btn-soft full" style="margin-top:12px" href="<?=legacy_base_url('pesanan/'.rawurlencode($case['order_number']))?>?token=<?=rawurlencode($case['public_token'])?>">Lihat Pesanan</a></aside></section><?php endif;?></main>
